-- ==============================================================================
-- 秦安县秦剧团云端预约系统 · PostgreSQL 13+ 初始化脚本 v1.0
-- 文档来源：F-1 §二（PG 13+ 备选栈 / E-5）
-- 类型映射（MySQL → PostgreSQL）：
--   DATETIME           → TIMESTAMP(0)
--   TINYINT(1)         → BOOLEAN
--   INT                → INTEGER
--   BIGINT UNSIGNED    → BIGINT GENERATED BY DEFAULT AS IDENTITY
--   DECIMAL(M,D)       → NUMERIC(M,D)
--   JSON               → JSONB（PG 推荐二进制JSON · 支持 GIN 索引）
--   MEDIUMTEXT/LONGTEXT→ TEXT
--   VARCHAR(N) COLLATE utf8mb4_0900_ai_ci → VARCHAR(N) COLLATE "zh_CN.utf8"
--   ON UPDATE CURRENT_TIMESTAMP → 触发器 trig_set_updated_at()
--   AUTO_INCREMENT     → GENERATED BY DEFAULT AS IDENTITY
--   CREATE INDEX IF NOT EXISTS → PG 9.5+ 原生支持
--   INSERT ... ON DUPLICATE KEY UPDATE → INSERT ... ON CONFLICT (pk) DO UPDATE SET
--   FOREIGN_KEY_CHECKS=0 → START TRANSACTION / SET CONSTRAINTS ALL DEFERRED
-- ==============================================================================
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;
SET default_table_access_method = heap;
SET timezone = 'Asia/Shanghai';

-- 启用 pgcrypto (UUID / 哈希函数，bcrypt需要 pgcrypto 扩展)
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;      -- 中文模糊搜索（姓名/电话 LIKE %xxx%）
CREATE EXTENSION IF NOT EXISTS btree_gin;   -- JSONB 字段支持

-- ------------------------------------------------------------------------------
-- 前置：3 层账号隔离（F-1 §2.0 / M-2 P0，PG 使用 ROLE 权限体系）
--   $DB_USER     → qaxqjt_app        CONNECT + SELECT/INSERT/UPDATE/DELETE
--   $DB_MIG_USER → qaxqjt_migrate    SUPERUSER 级（本机/容器使用）
--   $DB_READ     → qaxqjt_read       CONNECT + SELECT
-- 注：CREATE ROLE IF NOT EXISTS 需要 PG 14+，若 PG13 用 DO $$ 容错
-- ------------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='qaxqjt_app') THEN
    CREATE ROLE qaxqjt_app LOGIN PASSWORD '__APP_PASSWORD_FROM_ENV__';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='qaxqjt_migrate') THEN
    CREATE ROLE qaxqjt_migrate LOGIN PASSWORD '__MIGRATE_PASSWORD_FROM_ENV__' SUPERUSER;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='qaxqjt_read') THEN
    CREATE ROLE qaxqjt_read LOGIN PASSWORD '__READ_PASSWORD_FROM_ENV__';
  END IF;
END$$;

GRANT CONNECT ON DATABASE qaxqjt_prod TO qaxqjt_app, qaxqjt_read;
GRANT USAGE ON SCHEMA public TO qaxqjt_app, qaxqjt_read;

-- ------------------------------------------------------------------------------
-- PG 通用：updated_at 自动设为 NOW()（对应 MySQL ON UPDATE CURRENT_TIMESTAMP）
-- 用法：CREATE TABLE 之后执行 SELECT tg_set_updated_at('table_name');
-- ------------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION tg_set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := CURRENT_TIMESTAMP(0);
  RETURN NEW;
END; $$;

CREATE OR REPLACE PROCEDURE set_table_updated_at_trigger(tbl text) LANGUAGE plpgsql AS $$
DECLARE tg_name text := 'trg_' || tbl || '_set_updated_at';
BEGIN
  EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', tg_name, tbl);
  EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE ON %I
                  FOR EACH ROW EXECUTE FUNCTION tg_set_updated_at()', tg_name, tbl);
END; $$;

-- ------------------------------------------------------------------------------
-- 通用：ENUM 类型（与 MySQL ENUM 对应，PG 原生 CHECK + 枚举语义）
-- 为与 MySQL 版本保持 VARCHAR(xx) 可移植，我们仍用 VARCHAR + CHECK，
-- 下面 2 个 ENUM 仅用于语义更清晰的考勤类型与性别（可选）
-- ------------------------------------------------------------------------------
-- CREATE TYPE performer_gender AS ENUM ('男','女','其他');
-- CREATE TYPE attendance_category AS ENUM ('full','night','double','half','公休','rest',
--   'SL','PL','BL','ML','AL','absent','rainout','leave','outing','study','business','injury');

-- ------------------------------------------------------------------------------
-- 批次 1：权限模块基础（8 张）—— 与 MySQL 完全对齐
-- ------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS accounts_v2 (
  id                  VARCHAR(32)   PRIMARY KEY,
  username            VARCHAR(64)   NOT NULL UNIQUE,
  password_hash       VARCHAR(255)  NOT NULL,
  real_name           VARCHAR(50)   NOT NULL,
  role                VARCHAR(32)   NOT NULL DEFAULT 'staff',
  phone               VARCHAR(20),
  email               VARCHAR(128),
  avatar_url          VARCHAR(500),
  last_login_at       TIMESTAMP(0),
  last_login_ip       VARCHAR(45),
  force_pwd_change    BOOLEAN       NOT NULL DEFAULT TRUE,
  failed_login_count  INTEGER       NOT NULL DEFAULT 0,
  locked_until        TIMESTAMP(0),
  totp_secret         VARCHAR(64),
  status              VARCHAR(20)   NOT NULL DEFAULT 'active',
  created_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  updated_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  created_by          VARCHAR(32),
  updated_by          VARCHAR(32),
  _ts                 BIGINT        NOT NULL
);
CALL set_table_updated_at_trigger('accounts_v2');
COMMENT ON TABLE accounts_v2 IS '后台账号表 (M-14 初始超管 bcrypt+force_pwd_change)';

CREATE TABLE IF NOT EXISTS roles (
  id                  VARCHAR(32)   PRIMARY KEY,
  name                VARCHAR(50)   NOT NULL UNIQUE,
  description         VARCHAR(200),
  level               INTEGER       NOT NULL DEFAULT 100,
  status              VARCHAR(20)   NOT NULL DEFAULT 'active',
  created_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  updated_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  created_by          VARCHAR(32),
  updated_by          VARCHAR(32),
  _ts                 BIGINT        NOT NULL
);
CALL set_table_updated_at_trigger('roles');

CREATE TABLE IF NOT EXISTS permissions (
  id                  VARCHAR(32)   PRIMARY KEY,
  code                VARCHAR(80)   NOT NULL UNIQUE,
  name                VARCHAR(80)   NOT NULL,
  module              VARCHAR(32)   NOT NULL,
  description         VARCHAR(200),
  level_require       INTEGER       NOT NULL DEFAULT 100,
  status              VARCHAR(20)   NOT NULL DEFAULT 'active',
  created_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  updated_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  created_by          VARCHAR(32),
  updated_by          VARCHAR(32),
  _ts                 BIGINT        NOT NULL
);
CALL set_table_updated_at_trigger('permissions');

CREATE TABLE IF NOT EXISTS role_permissions (
  id                  VARCHAR(32)   PRIMARY KEY,
  role_id             VARCHAR(32)   NOT NULL,
  permission_code     VARCHAR(80)   NOT NULL,
  created_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  created_by          VARCHAR(32),
  _ts                 BIGINT        NOT NULL,
  CONSTRAINT uk_role_perm UNIQUE (role_id, permission_code)
);

CREATE TABLE IF NOT EXISTS user_roles (
  id                  VARCHAR(32)   PRIMARY KEY,
  account_id          VARCHAR(32)   NOT NULL,
  role_id             VARCHAR(32)   NOT NULL,
  assigned_at         TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  assigned_by         VARCHAR(32),
  _ts                 BIGINT        NOT NULL,
  CONSTRAINT uk_user_role UNIQUE (account_id, role_id)
);

CREATE TABLE IF NOT EXISTS admin_sessions (
  id                  VARCHAR(64)   PRIMARY KEY,
  account_id          VARCHAR(32)   NOT NULL,
  ip_address          VARCHAR(45),
  user_agent          VARCHAR(500),
  expires_at          TIMESTAMP(0)  NOT NULL,
  issued_at           TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  last_seen_at        TIMESTAMP(0),
  device_fingerprint  VARCHAR(128),
  revoked             BOOLEAN       NOT NULL DEFAULT FALSE,
  _ts                 BIGINT        NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_sess_expires ON admin_sessions(expires_at);

CREATE TABLE IF NOT EXISTS audit_logs (
  id                  VARCHAR(32)   PRIMARY KEY,
  account_id          VARCHAR(32),
  username_snapshot   VARCHAR(64)   NOT NULL,
  action              VARCHAR(64)   NOT NULL,
  module              VARCHAR(32)   NOT NULL,
  target_table        VARCHAR(64),
  target_id           VARCHAR(32),
  ip_address          VARCHAR(45),
  user_agent          VARCHAR(500),
  request_id          VARCHAR(64),
  before_snapshot     JSONB,
  after_snapshot      JSONB,
  diff_summary        VARCHAR(500),
  severity            VARCHAR(16)   NOT NULL DEFAULT 'info',
  action_ts           TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  _ts                 BIGINT        NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_audit_user_ts ON audit_logs(account_id, action_ts DESC);
COMMENT ON TABLE audit_logs IS 'E-2 审计日志 · 财务作废/越权403/备份下载必留痕';

CREATE TABLE IF NOT EXISTS login_attempts (
  id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username            VARCHAR(64),
  ip_address          VARCHAR(45)   NOT NULL,
  success             BOOLEAN       NOT NULL,
  fail_reason         VARCHAR(64),
  attempted_at        TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  user_agent          VARCHAR(500),
  _ts                 BIGINT        NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_login_ip_ts ON login_attempts(ip_address, attempted_at);

