  total_subsidy       NUMERIC(10,2) DEFAULT 0,
  meal_ticket_count   INTEGER DEFAULT 0,
  reason              VARCHAR(500),
  approved_by         VARCHAR(32),
  approved_at         TIMESTAMP(0),
  wage_posted         BOOLEAN       NOT NULL DEFAULT FALSE,
  created_at          TIMESTAMP(0)  NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  created_by          VARCHAR(32),
  _ts                 BIGINT        NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ot_staff ON overtime_records(staff_id, overtime_date);

-- ==============================================================================
-- 授权收尾：3 层数据库账号权限（M-2 P0）—— 仅对 qaxqjt_prod 库生效
--   qaxqjt_app  = 业务账号（读写无 DDL/DROP）
--   qaxqjt_read = 只读 BI 账号
-- ==============================================================================
GRANT SELECT, INSERT, UPDATE, DELETE
  ON ALL TABLES IN SCHEMA public TO qaxqjt_app;
GRANT SELECT, UPDATE
  ON ALL SEQUENCES IN SCHEMA public TO qaxqjt_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO qaxqjt_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, UPDATE ON SEQUENCES TO qaxqjt_app;

GRANT SELECT ON ALL TABLES IN SCHEMA public TO qaxqjt_read;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT ON TABLES TO qaxqjt_read;

